from collections.abc import Sequence
from fractions import Fraction
from typing import Tuple


def summarize_tokens(tokens: Sequence[str]) -> Tuple[int, Fraction]:
    if isinstance(tokens, (str, bytes)) or not isinstance(tokens, Sequence):
        raise ValueError("tokens must be a sequence of strings")

    total = 0
    count = 0
    stopped = False

    for token in tokens:
        if not isinstance(token, str):
            raise ValueError("every token must be a string")
        if stopped:
            raise ValueError("tokens are not allowed after STOP")

        stripped = token.strip()
        if stripped == "STOP":
            if count == 0:
                raise ValueError("at least one value is required")
            stopped = True
            continue

        try:
            value = int(stripped, 10)
        except ValueError as exc:
            raise ValueError("invalid integer token") from exc
        if value <= 0:
            raise ValueError("values must be positive")
        total += value
        count += 1

    if not stopped:
        raise ValueError("STOP is required")
    return count, total / count

